using EduVerse.Core.Catalog;
using EduVerse.Core.Common;
using Txt = EduVerse.Core.Catalog.Text;

namespace EduVerse.Core.Tutor;

/// <summary>
/// A short, plausible-sounding statement in the voice of an AI about a concept — sometimes true, sometimes subtly
/// and deliberately wrong — whose truth is always decided in code, never by the AI itself. <see cref="Explanation"/>
/// is shown after the student answers, whichever way they answered.
/// </summary>
public sealed record Claim(string Id, Area Area, Txt Statement, bool IsTrue, Txt Explanation);

/// <summary>
/// "Don't believe everything an AI tells you": the same pedagogy as <see cref="Pip"/> ("correct the AI student's
/// mistake"), extended from step-by-step numeric problems to one-line conceptual claims. The student is not asked to
/// spot an arithmetic slip but to judge a statement the way they would judge anything an AI says — which is the
/// point: this is explicitly about not trusting AI output blindly, not about the subject matter itself. Every claim
/// is decided in code (works offline too); nothing here is generated by an AI, on purpose.
/// </summary>
public static class PipClaims
{
    public const int Xp = 6;

    public const int RewardedPerDay = 6;

    private static Claim C(string id, Area area, string statement, bool isTrue, string explanation) =>
        new(id, area, Txt.Of(statement), isTrue, Txt.Of(explanation));

