    /// <summary>All curated claims, for tools and tests.</summary>
    public static IReadOnlyList<Claim> All() => Bank;

    public static Claim? Find(string id) => Bank.FirstOrDefault(c => c.Id == id);

    /// <summary>A round of up to <paramref name="count"/> distinct claims, mixing true and false ones, the same for the same
    /// seed (so the server does not need to remember which round a student is on). Limited to <paramref name="area"/> when
    /// given, falling back to every area if that leaves too few to fill the round.</summary>
    public static IReadOnlyList<Claim> Round(int seed, int count, Area? area = null)
    {
        var pool = area is { } a ? Bank.Where(c => c.Area == a).ToList() : Bank.ToList();
        if (pool.Count < count)
        {
            pool = Bank.ToList();
        }

        var rng = new Random(seed);
        return pool.OrderBy(_ => rng.Next()).Take(Math.Min(count, pool.Count)).ToList();
    }
